{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Background: There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The manuscript explicitly states the current limited evidence base for evaluating sustainability and highlights gaps/uncertainties about which approaches and outcomes are most effective."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Through an integrative review, we aimed to identify approaches to evaluate the sustainability of evidence-based interventions (EBIs) and sustainability outcomes.",
      "reason": "The abstract states the review objective and frames the importance/need to identify evaluation approaches and outcomes due to limited existing evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. We found 64 studies in the peer-review literature that used a theoretical approach to evaluate the sustainability of EBIs in healthcare. Our synthesis indicated that there is a breadth of theoretical approaches and constructs that were considered for the evaluation of the sustainability of EBIs in healthcare that were consistent with other recent synthesis work [6-10]. In a review by Lennox et al., they indicated that only 21% of studies reported any information on sustainability outcomes [6].",
      "reason": "The discussion compares this review to prior syntheses, cites previous reviews (e.g., Lennox et al.), and explains how and why the current review is needed/different from existing reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is an integrative review of evaluation approaches for sustainability rather than a review of intervention effects; no proposed mechanism of action of an intervention is described and the item is conditional to intervention-effect reviews."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model is presented or discussed; the review focuses on evaluation approaches for sustainability rather than presenting a hypothesised intervention-outcome logic model, so this conditional element does not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The manuscript explicitly states clear objectives/aims to identify and synthesize approaches and to enhance understanding of specific aspects of sustainability evaluation. However, the objectives are not presented using a recognised question-formulation framework (e.g., PICO, PICOS, or similar), so the requirement to use a relevant question-formulation framework is not met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "We conducted an integrative review that followed Whittemore and Knafl's [12] five-stage methodological process: (1) problem identification; (2) literature search; (3) data evaluation; (4) data analysis (data reduction, display, comparison, and conclusions); and (5) presentation. Integrative reviews can include diverse data sources and do not restrict the type of study design.",
      "reason": "This is an integrative review aiming to identify and synthesize approaches to evaluate sustainability of EBIs rather than a review of intervention effects with planned comparisons; thus PICO-style planned comparisons for intervention effects do not apply."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical ­ approach a for sustainability ­ (theory b , ­ model c , ­ framework d , ­ instrument e , method, checklist, process, strategy, conceptual- izations, development, pilot test and/or ­ tool f ) • Were within a healthcare ­ setting g • Evaluated the sustainability of an EBI (Note that inconsistent terminology for EBI is prominent and thus may be referred to as a QI intervention/ initia- tive in the literature).",
      "reason": "Table 1 explicitly lists study characteristics used for eligibility including study design, theoretical approach, setting, and that studies must evaluate sustainability of an EBI."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. This review entailed a comprehensive search of published literature and rigorous review methods; however, we recognize that there is the possibility of incomplete retrieval of identified research. For example, all gray literature was excluded.",
      "reason": "The manuscript specifies language (English) and publication/report status (published, peer-reviewed; gray literature excluded) but does not specify any dissemination year restrictions."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured versus exclusion because outcome results were not reported is found in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not specify groups used in each synthesis nor link groups to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. ... For example, all gray literature was excluded.",
      "reason": "Notable eligibility restrictions (English language, peer-reviewed publications, exclusion of gray literature) are reported, but no substantive rationale is provided explaining why these restrictions were imposed."
    }
  ],
  "confidence": 85
}

